<?php
/**
 * Plugin Name: LingoCanvas smoke domain
 * Description: Smoke-test fixture (bin/smoke-test.sh, scenario S6): a third-party text domain with
 *              __(), _x(), _n() and an untranslated string. Its Russian .mo is generated by the test.
 * Version: 1.0.0
 * Text Domain: lingocanvas-smoke-domain
 *
 * Not part of the plugin ZIP.
 */

add_shortcode(
	'lingocanvas_smoke_domain',
	static function (): string {
		$out  = '<div id="smoke-domain">';
		$out .= '<p class="smoke-singular">[' . esc_html( __( 'Smoke singular', 'lingocanvas-smoke-domain' ) ) . ']</p>';
		$out .= '<p class="smoke-ctx">[' . esc_html( _x( 'Smoke ctx', 'smoke-context', 'lingocanvas-smoke-domain' ) ) . ']</p>';

		foreach ( array( 1, 2, 5 ) as $n ) {
			/* translators: %d: number of smoke items */
			$out .= '<p class="smoke-plural-' . $n . '">[' . esc_html( sprintf( _n( '%d smoke item', '%d smoke items', $n, 'lingocanvas-smoke-domain' ), $n ) ) . ']</p>';
		}

		$out .= '<p class="smoke-untranslated">[' . esc_html( __( 'Smoke untranslated', 'lingocanvas-smoke-domain' ) ) . ']</p>';

		return $out . '</div>';
	}
);
